div.script:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {"@type": "Question", "name": "Is the app really free?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. Odoo Mobile Client is free to download and free to use, with no user limit and no trial period. The Advanced edition is also a free download — you only pay for its server module on the Odoo App Store."}},
    {"@type": "Question", "name": "Do I need to have Odoo to use the app?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. Odoo Mobile Client is an access client: it connects to an Odoo server that you or your company control, and it does not host any data of its own."}},
    {"@type": "Question", "name": "Do I need to change anything on my Odoo server?", "acceptedAnswer": {"@type": "Answer", "text": "One small step: install the connector module from the Odoo App Store — odoo_mobile_client (free) for the Free edition, odoo_mobile_client_advanced (paid) for Advanced."}},
    {"@type": "Question", "name": "Does it work with Odoo Enterprise, Odoo.sh and Community?", "acceptedAnswer": {"@type": "Answer", "text": "Yes — Community and Enterprise, wherever hosted. OMC Free supports Odoo 12 to 19+, and OMC Advanced supports Odoo 17 to 19+."}},
    {"@type": "Question", "name": "Where are my username and password stored?", "acceptedAnswer": {"@type": "Answer", "text": "Only on your phone, inside the operating system's secure storage (Keychain on iOS, Keystore on Android). They are sent only to the Odoo server you configure."}},
    {"@type": "Question", "name": "Can I connect more than one Odoo server?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. The Free edition saves up to two servers and switches between them without typing credentials again. The Advanced edition removes the limit."}},
    {"@type": "Question", "name": "What does the Advanced edition add?", "acceptedAnswer": {"@type": "Answer", "text": "Unlimited saved servers, in-app branding with your colors and logo, push notifications for activities and messages, QR onboarding, barcode and document scanners, and connected device management. One-time purchase, available now."}}
  ]
}
